package com.bank.search.spec;

import com.bank.search.model.Account;
import org.springframework.data.jpa.domain.Specification;
import java.math.BigDecimal;

// One reusable, testable Specification per optional filter.
// Returning null when the input is absent means "skip this filter".
public final class AccountSpecifications {
    private AccountSpecifications() { }

    public static Specification<Account> hasType(String type) {
        return (root, q, cb) -> type == null ? null : cb.equal(root.get("type"), type);
    }
    public static Specification<Account> hasStatus(String status) {
        return (root, q, cb) -> status == null ? null : cb.equal(root.get("status"), status);
    }
    public static Specification<Account> balanceAtLeast(BigDecimal min) {
        return (root, q, cb) -> min == null ? null
                : cb.ge(root.get("balance"), min);
    }
    public static Specification<Account> nameContains(String fragment) {
        return (root, q, cb) -> fragment == null ? null
                : cb.like(cb.lower(root.get("holderName")), "%" + fragment.toLowerCase() + "%");
    }
}
