package com.bank.search.service;

import com.bank.search.dto.AccountSearchCriteria;
import com.bank.search.model.Account;
import com.bank.search.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.data.domain.*;
import org.springframework.data.jpa.domain.Specification;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import static com.bank.search.spec.AccountSpecifications.*;

@Service
@RequiredArgsConstructor
@Slf4j
public class AccountSearchService {

    private final AccountRepository accountRepo;

    @Transactional(readOnly = true)
    public Page<Account> search(AccountSearchCriteria c, int page, int size) {
        // Compose ONLY the filters that were supplied — null specs drop out.
        Specification<Account> spec = Specification
                .where(hasType(c.type()))
                .and(hasStatus(c.status()))
                .and(balanceAtLeast(c.minBalance()))
                .and(nameContains(c.nameContains()));

        Pageable pageable = PageRequest.of(page, size, Sort.by("balance").descending());
        Page<Account> result = accountRepo.findAll(spec, pageable);
        log.info("Search matched {} accounts (page {}/{})",
                result.getTotalElements(), page, result.getTotalPages());
        return result;
    }
}
```

