package com.bank.search.controller;

import com.bank.search.dto.AccountSearchCriteria;
import com.bank.search.model.Account;
import com.bank.search.service.AccountSearchService;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.Page;
import org.springframework.web.bind.annotation.*;
import java.math.BigDecimal;

@RestController
@RequestMapping("/api/v1/accounts")
@RequiredArgsConstructor
public class AccountSearchController {

    private final AccountSearchService searchService;

    @GetMapping("/search")
    public Page<Account> search(
            @RequestParam(required = false) String type,
            @RequestParam(required = false) String status,
            @RequestParam(required = false) BigDecimal minBalance,
            @RequestParam(required = false) String nameContains,
            @RequestParam(defaultValue = "0") int page,
            @RequestParam(defaultValue = "20") int size) {
        return searchService.search(
                new AccountSearchCriteria(type, status, minBalance, nameContains), page, size);
    }
}
